import { badge, button, emptyState, escapeHtml as e, money, pageHeading } from "./ui.js";
import { linkedChildren } from "./access.js";
import { notifications } from "./notifications-data.js";
import { feeInvoices } from "./fees-data.js";
import { trackingPolicy, transportNow } from "./transport-privacy.js";
const card = (title, content) => `<section class="surface portal-card"><h2>${title}</h2>${content}</section>`;
export function familyPage({ state, context }) {
  const children = linkedChildren(state, context), feed = notifications(state, context), todos = feed.filter((item) => item.todo), fees = feeInvoices(state, context);
  return `${pageHeading("Your family, connected", e(context.account.name) + " · " + children.length + " linked children", '<a class="button secondary" href="#parent/inbox">Inbox · ' + feed.filter((item) => !item.read).length + ' unread</a>')}
    <div class="portal-banner"><div><span class="eyebrow">FAMILY ACCOUNT</span><h2>One login. Every school day.</h2><p>${e(context.account.familyLogin || "Linked guardian account")}</p></div><a class="button secondary" href="#parent/events">Events & consent</a></div>
    <div class="family-grid">${children.map((child) => `<section class="surface portal-card family-child"><div class="family-initials">${e(child.initials)}</div><h2>${e(child.name)}</h2><p>${e(child.admissionNumber)} · Class ${e(child.className)}</p><p>${e(state.branches.find((item) => item.id === child.branch)?.name)}</p><div class="portal-actions">${button("View child", "family-child", { value: child.id })}${button("Track bus", "family-bus", { value: child.id, variant: "secondary" })}</div></section>`).join("")}</div>
    <div class="portal-grid">${card("To do · " + todos.length, todos.slice(0, 6).map((item) => `<button class="portal-list-link portal-todo-link" type="button" data-action="portal-open" data-value="${e(item.id)}"><span><strong>${e(item.title)}</strong><small>${e(item.message)}</small><small>${e(children.filter((child) => item.studentIds.includes(child.id)).map((child) => child.name).join(", "))}</small></span><span>→</span></button>`).join("") || "<p>You’re all caught up.</p>")}${card("Family fee balance", `<div class="portal-big-number">${money(fees.reduce((sum, item) => sum + item.balance, 0) / 100)}</div><p>Across ${children.length} linked children</p><a class="button secondary" href="#parent/fees">View school fees</a>`)}</div>`;
}
export function inboxPage({ state, context, portal = {} }) {
  const all = notifications(state, context), filter = portal.inbox || "all", feed = all.filter((item) => filter === "all" || filter === "todo" && item.todo || filter === "unread" && !item.read || filter === "transport" && item.category === "Transport");
  return `${pageHeading("Notifications & to do", "School updates in one place · In-portal demo")}
    <div class="portal-tabs">${[["all", "All updates"], ["unread", "Unread"], ...(context.role === "parent" ? [["todo", "To do"]] : []), ["transport", "Transport"]].map(([id, label]) => button(label + " · " + all.filter((item) => id === "all" || id === "unread" && !item.read || id === "todo" && item.todo || id === "transport" && item.category === "Transport").length, "portal-inbox-filter", { value: id, variant: filter === id ? "primary" : "secondary" })).join("")}</div>
    <div class="portal-feed">${feed.map((item) => `<article class="surface portal-card notification-card ${item.urgent ? "urgent" : ""} ${item.read ? "is-read" : ""}"><div class="portal-row">${badge(e(item.category), item.urgent ? "amber" : "blue")}${badge(item.read ? "Read" : "New", item.read ? "neutral" : "green")}${item.todo ? badge("Action needed", "amber") : ""}</div><h2>${e(item.title)}</h2><p>${e(item.message)}</p><p class="portal-muted">${e(String(item.at || "").slice(0, 16).replace("T", " "))} UTC · ${e(state.students.filter((student) => item.studentIds.includes(student.id)).map((student) => student.name).join(", "))}</p><div class="portal-actions">${context.role === "parent" ? button("Open", "portal-open", { value: item.id }) : ""}${!item.read ? button("Mark read", "portal-read", { value: item.id, variant: "secondary" }) : ""}</div></article>`).join("") || `<section class="surface">${emptyState("checkCircle", "No updates here", "You’re up to date with this view.")}</section>`}</div>`;
}
export function morePage({ context }) {
  return pageHeading("Explore your portal", "School essentials, learning and communication") + '<div class="family-grid">' + [["subjects", "Subjects"], ["homework", "Homework"], ["notices", "Notices"], ["events", "Events & consent"], ["communications", "Letters & email"], ["library", "Pupil’s books"], ["uniforms", "School uniforms"], ["boarding", "Bus boarding"]].map(([id, label]) => `<a class="surface portal-card portal-list-link" href="#${context.role}/${id}"><h2>${label}</h2><span>→</span></a>`).join("") + '</div>';
}
export function trackingPage({ state, context }) {
  const bus = state.buses.find((item) => item.branch === context.branch), policy = trackingPolicy(state, bus || { branch: context.branch }), { settings, clock } = policy;
  return pageHeading("Tracking hours & alerts", "Pickup and drop-off privacy · Asia/Colombo") + `<div class="portal-grid"><section class="surface portal-card"><h2>GPS visibility hours</h2><p>${e(clock.date)} · ${e(clock.time)} · ${clock.demo ? "Demo clock" : "Sri Lanka clock"}</p><form data-form="portal-tracking"><div class="portal-form-grid">${[["pickupStart", "Pickup starts"], ["pickupEnd", "Pickup ends"], ["dropoffStart", "Drop-off starts"], ["dropoffEnd", "Drop-off ends"]].map(([id, label]) => `<label>${label}<input type="time" name="${id}" value="${settings[id]}" required></label>`).join("")}</div><label>Clock<select name="mode"><option value="demo" ${clock.demo ? "selected" : ""}>Presenter demo clock</option><option value="live" ${!clock.demo ? "selected" : ""}>Current Sri Lanka time</option></select></label><div class="portal-form-grid"><label>Demo date<input type="date" name="date" value="${e(clock.date)}" required></label><label>Demo time<input type="time" name="time" value="${e(clock.time)}" required></label></div><p>Weekdays only. Locations are hidden when a trip completes or the time window closes.</p><p class="form-error" hidden role="alert"></p><button class="button primary">Save tracking hours</button></form></section>
    <section class="surface portal-card"><h2>Notify families & class teachers</h2><form data-form="portal-transport-alert"><label>Bus<select name="busId">${state.buses.filter((item) => item.branch === context.branch).map((item) => `<option value="${e(item.id)}">Bus ${e(item.id)} · ${e(item.name)}</option>`).join("")}</select></label><label>Issue<select name="kind"><option value="late">Bus running late</option><option value="breakdown">Breakdown</option><option value="other">Other travel issue</option><option value="resolved">Issue resolved</option></select></label><label>Message to parents<textarea name="message" maxlength="500" required placeholder="Bus 01 is approximately 15 minutes late. Please wait at your usual pickup point."></textarea></label><p>Delivered to linked families and current class teachers of students allocated to this bus. In-portal demo only.</p><p class="form-error" hidden role="alert"></p><button class="button primary">Send transport alert</button></form></section></div><section class="surface portal-card"><h2>School trip privacy</h2>${state.buses.filter((bus) => bus.branch === context.branch).map((bus) => { const policy = trackingPolicy(state, bus); return `<div class="portal-list-link"><div><strong>Bus ${e(bus.id)}</strong><p>${e(policy.reason)}</p></div>${policy.visible ? button("Complete " + policy.direction + " trip", "portal-complete-trip", { value: bus.id, variant: "secondary" }) : badge("GPS hidden", "neutral")}</div>`; }).join("")}</section><section class="surface portal-card"><h2>Recent school alerts</h2>${(state.transportAlerts || []).filter((item) => item.branch === context.branch).slice().reverse().map((item) => `<div class="portal-list-link"><div><strong>Bus ${e(item.busId)} · ${e(item.kind)}</strong><p>${e(item.message)}</p></div></div>`).join("") || "<p>No school alerts sent yet.</p>"}</section>`;
}
